import { getDataSource } from '../data-source.js';
import { PacienteEntity } from '../entities/Paciente.class.js';
import type { TNewPaciente } from '../types/paciente.js';

/**
 * Inserts a patient and returns the paciente_id generated by the database
 */
export const createPaciente = async (data: TNewPaciente): Promise<number> => {
  const repository = (await getDataSource()).getRepository(PacienteEntity);
  const result = await repository.insert(data);
  const pacienteId = Number(result.identifiers[0]?.paciente_id);
  if (!Number.isInteger(pacienteId)) {
    throw new Error('The database did not return the paciente_id');
  }
  return pacienteId;
};
